-- Schema for the Kanban Task Board.
-- All IDs are UUID v4 strings generated by the application (crypto.randomUUID()).
-- Timestamps are ISO-8601 UTC strings.
-- Constraints here duplicate the zod validation as a second line of defence.

CREATE TABLE IF NOT EXISTS users (
  id            TEXT PRIMARY KEY CHECK (length(id) = 36),
  username      TEXT NOT NULL UNIQUE COLLATE NOCASE
                CHECK (length(username) BETWEEN 3 AND 32),
  email         TEXT NOT NULL UNIQUE COLLATE NOCASE
                CHECK (length(email) BETWEEN 3 AND 254),
  password_hash TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
  phone         TEXT CHECK (phone IS NULL OR length(phone) <= 20),
  bio           TEXT CHECK (bio IS NULL OR length(bio) <= 1000),
  is_disabled   INTEGER NOT NULL DEFAULT 0 CHECK (is_disabled IN (0, 1)),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Only an HMAC of the session token is stored, so a leaked DB cannot be replayed as cookies.
CREATE TABLE IF NOT EXISTS sessions (
  id          TEXT PRIMARY KEY CHECK (length(id) = 36),
  token_hash  TEXT NOT NULL UNIQUE,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  csrf_token  TEXT NOT NULL,
  expires_at  INTEGER NOT NULL,           -- epoch milliseconds
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_expires ON sessions(expires_at);

CREATE TABLE IF NOT EXISTS projects (
  id          TEXT PRIMARY KEY CHECK (length(id) = 36),
  owner_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),
  visibility  TEXT NOT NULL DEFAULT 'private' CHECK (visibility IN ('private', 'public')),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_projects_owner ON projects(owner_id);
CREATE INDEX IF NOT EXISTS idx_projects_visibility ON projects(visibility);

CREATE TABLE IF NOT EXISTS tasks (
  id          TEXT PRIMARY KEY CHECK (length(id) = 36),
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  created_by  TEXT REFERENCES users(id) ON DELETE SET NULL,
  title       TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 5000),
  status      TEXT NOT NULL DEFAULT 'todo' CHECK (status IN ('todo', 'in_progress', 'done')),
  priority    TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high')),
  due_date    TEXT CHECK (due_date IS NULL OR due_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  position    INTEGER NOT NULL DEFAULT 0 CHECK (position >= 0),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_tasks_project_status ON tasks(project_id, status);

CREATE TABLE IF NOT EXISTS comments (
  id          TEXT PRIMARY KEY CHECK (length(id) = 36),
  task_id     TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  author_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  body        TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 2000),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_comments_task ON comments(task_id);

CREATE TABLE IF NOT EXISTS attachments (
  id            TEXT PRIMARY KEY CHECK (length(id) = 36),
  task_id       TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  uploader_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  original_name TEXT NOT NULL CHECK (length(original_name) BETWEEN 1 AND 255),
  stored_name   TEXT NOT NULL UNIQUE
                CHECK (length(stored_name) = 32 AND stored_name NOT GLOB '*[^0-9a-f]*'),
  mime_type     TEXT NOT NULL CHECK (mime_type IN
                  ('image/png', 'image/jpeg', 'image/gif', 'application/pdf', 'text/plain')),
  size_bytes    INTEGER NOT NULL CHECK (size_bytes > 0),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_attachments_task ON attachments(task_id);
